from pydantic import BaseModel, Field
from typing import List, Optional

class JudgmentMatchFeature(BaseModel):
    """Captures the distinct features of a legal judgment document needed to match it against a list of outcomes."""

    case_number: Optional[str] = Field(
        description="The official case number of the current judgment document."
    )

    court_name: Optional[str] = Field(
        description="The name of the court that issued the judgment."
    )

    parties_involved: List[str] = Field(
        description="Names of the key parties involved (e.g., appellants, defendants, appellants)."
    )

    referenced_case_numbers: List[str] = Field(
        description="Case numbers of cases referenced in the judgment (e.g., the original case being appealed or reviewed)."
    )

    case_type: Optional[str] = Field(
        description="The nature of the case (e.g., Civil, Criminal, Administrative, Execution)."
    )

    verdict_logic: Optional[str] = Field(
        description="A high-level summary of the court's decision (e.g., 'Dismiss appeal, uphold', 'Revoke original', 'Modify sentence')."
    )

    specific_amounts: List[str] = Field(
        description="Specific monetary amounts mentioned in the verdict (e.g., compensation fees, fines, court costs)."
    )

    sentencing_details: Optional[str] = Field(
        description="Specific details of the sentence in criminal cases (e.g., '15 years', '1 year probation')."
    )

    legal_keywords: List[str] = Field(
        description="Specific phrases or legal articles cited that are unique to this decision's reasoning."
    )

class Parse(BaseModel):
    documents: List[JudgmentMatchFeature]
